    LANGUAGE_WRAPPER = 'In a combinatorial game, a single positive integer n with 1 \\le n \\le {upper_bound} is written on the blackboard. A move consists of selecting any positive integer k currently on the board with k > {threshold}, then choosing one split-size s from the set \\{{split_a}, {split_b}\\}, and erasing k to replace it by s non-negative integers that sum to k and whose pairwise differences are at most 1. (Equivalently, if k = sq + r with 0 \\le r < s, the replacement multiset is q repeated s - r times and q + 1 repeated r times; integers \\le {threshold} cannot be replaced.) The game ends when no valid move exists; the player who cannot move loses under normal play. Assuming optimal play, how many starting values n in \\{1, 2, \\dots, {upper_bound}\\} are winning for Player 1?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose two distinct split sizes >= 3 to ensure nontrivial take-and-break behavior.
while True:
