# Threshold must be at least 1; keep it not too large to ensure multiple levels of splitting appear.
t = rng.randint(1, min(a, b) - 1)
# Upper bound large enough to be nontrivial but small enough for fast verification.
U = rng.randint(120000, 300000)
# Avoid reproducing the seed exactly.
if not (a == 5 and b == 5 and t == 1 and U == 10000):
    return {
        'upper_bound': U,
        'threshold': t,
        'split_a': a,
        'split_b': b
    }
# Fallback (unlikely): regenerate.
return generator(rng)

    def verifier(assign):
# Validate domain and recompute the correct answer using Sprague-Grundy theory for take-and-break games.
try:
    U = int(assign.get('upper_bound'))
    t = int(assign.get('threshold'))
    a = int(assign.get('split_a'))
    b = int(assign.get('split_b'))
except Exception:
    # Invalid types
    return (False, None)
# Basic constraints
