    # Upper bound too small
    return (False, None)
if t < 1:
    # Threshold must be at least 1
    return (False, None)
if a < 3 or b < 3 or a == b:
    # Split sizes must be distinct and at least 3 to avoid trivialities and ensure termination structure.
    return (False, None)
# Compute Grundy numbers g[n] for n = 0..U under normal play.
# Base: g[n] = 0 for n <= t; zeros and small numbers are terminal.
g = [0] * (U + 2)
# Helper: mex of a small set (size at most 2 here)
def mex(vals):
    # vals is an iterable of nonnegative ints
    s = set(vals)
    m = 0
    while m in s:
        m += 1
    return m
# Fill bottom-up so references to g[q] and g[q+1] are available.
for n in range(t + 1, U + 1):
    options = []
    for s in (a, b):
        q = n // s
        r = n - s * q  # n % s
        x = 0
        # XOR of (s - r) copies of g[q] and r copies of g[q+1]
        if ((s - r) % 2) == 1:
            x ^= g[q]
        if (r % 2) == 1:
            x ^= g[q + 1]
        options.append(x)
    g[n] = mex(options)
# Count starting n in 1..U that are winning (nonzero Grundy value)
wins = sum(1 for n in range(1, U + 1) if g[n] != 0)
return (True, wins)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
